function UsersLayoutInner() {
  const [page, setPage] = useState(1);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = { page, page_size: PAGE_SIZE } as Inputs["users"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.users.list(input) });
  const matchRoute = useMatchRoute();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Users" count={list.data?.page.total}>
          
        </PaneHeader>


        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>No users yet.</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    to="/users/$id" params={{ id: text(row.id) }}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", Boolean(matchRoute({ to: "/users/$id", params: { id: text(row.id) } })) && "border-primary bg-accent")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.name) || "User " + text(row.id)}</div>
                    <div className="truncate text-xs text-muted-foreground">{[text(row.email), text(row.role), (row.banned ? "Banned" : "Not banned"), text(row.phone)].filter(Boolean).join(" · ")}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        <Outlet />
      </section>
    </div>
  );
}

function UsersIndexInner() {
  return <EmptyPane>Select an user from the list.</EmptyPane>;
}

function UsersDetailInner() {
  const { id: rawId } = useParams({ from: "/users/$id" });
  const id = idOf(rawId);
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.users.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["users"]["update"]) => client.users.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const banAction = useMutation({
    mutationFn: (input: Inputs["users"]["ban"]) => client.users.ban(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.name) || "User " + text(row.id)}
      actions={
        <>
          {canBan(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setOpenAction(open => (open === "ban" ? null : "ban"))}>
              Ban
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
        </>
      }
    >
      {openAction === "ban" ? (
        <div className="mb-6 rounded-md border border-border p-4">
          <UsersBanForm fields={USERSBAN_CREATE} initial={EMPTY_USERSBAN} submitLabel="Ban" pending={banAction.isPending} error={banAction.error} onCancel={() => setOpenAction(null)} onSubmit={values => banAction.mutate({ id, ...toUsersBanCreateInput(values) })} />
        </div>
      ) : null}

      {editing ? (
        <UsersForm
          fields={offeredUsers(USERS_UPDATE, field => field in row)}
          initial={usersFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: sentUsers(toUsersUpdateInput(values), field => field in row) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Email">{text(row.email) || "—"}</FieldRow>
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Role">{row.role == null ? "—" : <Badge variant="secondary">{text(row.role)}</Badge>}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Banned">{row.banned == null ? "—" : <Badge variant={row.banned ? "default" : "outline"}>{yesNo(row.banned)}</Badge>}</FieldRow>
        {"banned_at" in row ? (
          <FieldRow label="Banned At">{formatDateTime(row.banned_at) || "—"}</FieldRow>
        ) : null}
        <FieldRow label="Ban Reason">
          <p className="whitespace-pre-wrap">{text(row.ban_reason) || "—"}</p>
        </FieldRow>
        <FieldRow label="Post Count">{text(row.post_count) || "—"}</FieldRow>
        <FieldRow label="Approved Count">{text(row.approved_count) || "—"}</FieldRow>
        {"phone" in row ? (
          <FieldRow label="Phone">{text(row.phone) || "—"}</FieldRow>
        ) : null}
        <FieldRow label="Preferences">
          <pre className="overflow-x-auto rounded-md bg-muted p-3 text-xs">{formatJson(row.preferences) || "—"}</pre>
        </FieldRow>
        {"recovery_code" in row ? (
          <FieldRow label="Recovery Code">{text(row.recovery_code) || "—"}</FieldRow>
        ) : null}
        <FieldRow label="Posts">
          {row.posts.length === 0 ? (
            "—"
          ) : (
            <ul className="space-y-1">
              {row.posts.map(item => (
                <li key={text(item.id)}>{text(item.title)}</li>
              ))}
            </ul>
          )}
        </FieldRow>
        </dl>
      )}
    </Pane>
  );
}

export const UsersLayout = guarded(UsersLayoutInner);
export const UsersIndex = guarded(UsersIndexInner);
export const UsersDetail = guarded(UsersDetailInner);
